<script setup lang="ts">
import { ArrowLeft,FileText,CalendarDays,UserRound,Download,Info,MessageCircle,ArrowRight } from 'lucide-vue-next'
import type {Application} from '~/types/models'
const id=String(useRoute().params.id)
const {data:c,error}=await useFetch<Application>(`/api/applications/${id}`, {key:`citizen-application:${id}`})
const {date,dateTime,bytes}=useFormat()
const message=ref('');const notice=ref('');const sending=ref(false)
async function sendMessage(){sending.value=true;notice.value='';try{await $fetch('/api/support',{method:'POST',body:{applicationId:id,message:message.value}});message.value='';notice.value='Đã gửi câu hỏi (bản mô phỏng).'}catch(e){notice.value=readableError(e)}finally{sending.value=false}}
</script>
<template><div class="space-y-4"><NuxtLink to="/ho-so" class="inline-flex items-center gap-1 text-sm font-semibold text-brand-700"><ArrowLeft :size="16"/>Danh sách hồ sơ</NuxtLink><div v-if="error" class="panel p-6 text-rose-600">Không tìm thấy hồ sơ hoặc không có quyền truy cập.</div><template v-else-if="c"><div class="panel p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold text-muted">Mã hồ sơ: {{c.id}}</p><h2 class="mt-1 text-xl font-black">{{c.procedure_title}}</h2></div><StatusPill :status="c.status"/></div><div class="mt-4 grid gap-3 border-t pt-4 text-sm sm:grid-cols-3"><div><span class="text-xs text-muted">Người nộp</span><p class="font-bold">{{c.applicant_name}}</p></div><div><span class="text-xs text-muted">Ngày tiếp nhận</span><p class="font-bold">{{c.status==='draft'?'Chưa nộp':dateTime(c.submitted_at)}}</p></div><div><span class="text-xs text-muted">Hạn xử lý (dự kiến)</span><p class="font-bold">{{c.status==='draft'?'Chưa tính':date(c.due_at)}}</p></div></div></div>
 <section class="panel p-5"><h3 class="section-label">Tiến độ xử lý hồ sơ</h3><CaseTimeline :status="c.status"/><div class="mt-4 border-t border-slate-100 pt-3"><div v-for="e in c.events" :key="e.id" class="flex gap-3 border-b border-slate-100 py-3 last:border-b-0"><span class="mt-1 h-3 w-3 shrink-0 rounded-full bg-blue-500"/><div><p class="text-sm font-bold">{{e.note}}</p><p class="mt-1 text-xs text-muted">{{dateTime(e.created_at)}} · {{e.actor_name}}</p></div></div></div></section>
 <div class="grid min-w-0 gap-4 lg:grid-cols-2"><section class="panel p-4"><h3 class="section-label"><FileText :size="20" class="text-blue-600"/>Giấy tờ đã nộp ({{c.documents?.length||0}})</h3><div v-if="!c.documents?.length" class="p-3 text-sm text-muted">Chưa có tệp đính kèm.</div><div v-for="d in c.documents" :key="d.id" class="flex min-w-0 items-center justify-between gap-2 border-b py-3 last:border-0"><span class="min-w-0 text-sm"><b class="block truncate">{{d.original_name}}</b><small class="text-muted">{{bytes(d.size_bytes)}} · {{dateTime(d.uploaded_at)}}</small></span><a :href="`/api/documents/${d.id}`" class="btn-outline !p-2" aria-label="Tải tài liệu"><Download :size="16"/></a></div></section><section class="panel p-4"><h3 class="section-label"><MessageCircle :size="20" class="text-brand-600"/>Gửi câu hỏi về hồ sơ</h3><form class="space-y-3" @submit.prevent="sendMessage"><textarea v-model="message" class="field" rows="4" maxlength="2000" minlength="5" required placeholder="Nhập nội dung cần trao đổi..."/><p v-if="notice" class="text-xs text-brand-700">{{notice}}</p><button class="btn-primary" :disabled="sending||message.trim().length<5" type="submit">Gửi câu hỏi <ArrowRight :size="15"/></button></form></section></div>
 <div class="flex flex-wrap gap-3"><NuxtLink v-if="c.status==='supplement'" :to="`/ho-so/${c.id}/bo-sung`" class="btn-primary">Bổ sung giấy tờ <ArrowRight :size="16"/></NuxtLink><NuxtLink v-if="c.status==='completed'" :to="`/ho-so/${c.id}/ket-qua`" class="btn-primary">Xem kết quả <ArrowRight :size="16"/></NuxtLink><NuxtLink v-if="c.status==='draft'" :to="`/nop-ho-so/${c.procedure_id}?draft=${c.id}&step=2`" class="btn-primary">Tiếp tục hồ sơ nháp <ArrowRight :size="16"/></NuxtLink></div></template></div></template>
